contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        bool callerIsOwner = (msg.sender == c.owner());

        assert(
            reverted == !callerIsOwner
            && afterCount == beforeCount
            && (
                (reverted && afterBalance == beforeBalance)
                || (!reverted && afterBalance == 0)
            )
        );
    }

    receive() external payable {}
}

